import java.util.*;

public class Main {
    static long large_INF = (long) 1e18;
    static long total_result = 0;
    static Long[] memo_table;

    static int compute_min_moves(long n) {
        if (n == 0) return 0;
        if (n < memo_table.length && memo_table[(int) n] != null) return memo_table[(int) n];

        long min_difference = large_INF;
        long val = 1;
        int move_count = 0;

        while (Math.abs(val - n) <= min_difference) {
            min_difference = Math.abs(val - n);
            val = val * 10 + 1;
            move_count++;
        }
        val /= 10;

        if (val > n && val / 10 > 0) {
            if (n < memo_table.length) {
                int res1 = move_count + compute_min_moves(Math.abs(val - n));
                int res2 = move_count - 1 + compute_min_moves(Math.abs(val / 10 - n));
                int result = Math.min(res1, res2);
                memo_table[(int) n] = (long) result;
                return result;
            } else {
                int res1 = move_count + compute_min_moves(Math.abs(val - n));
                int res2 = move_count - 1 + compute_min_moves(Math.abs(val / 10 - n));
                return Math.min(res1, res2);
            }
        }
        if (n < memo_table.length) {
            int res = move_count + compute_min_moves(Math.abs(val - n));
            memo_table[(int) n] = (long) res;
            return res;
        }
        return move_count + compute_min_moves(Math.abs(val - n));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        memo_table = new Long[10000000];
        System.out.println(compute_min_moves(n));
        sc.close();
    }
}
